from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
years={2019,2020,2021,2022,2023,'2019','2020','2021','2022','2023'}
print('Searching Data sheet for year-like headers/values 2019-2023:')
found=[]
for r in range(1, ws.max_row+1):
    for c in range(1, ws.max_column+1):
        v=ws.cell(r,c).value
        if v in years:
            found.append((r,get_column_letter(c),v))
print(found if found else 'No literal year headers found on Data sheet')
print('\nData rows 1-22 A:L:')
for r in range(1,23):
    vals={get_column_letter(c): ws.cell(r,c).value for c in range(1,13)}
    if any(v is not None for v in vals.values()) or r>=18:
        print(f'Row {r}:', vals)
